package me.cryo.zombierool.client.career;
import com.google.gson.*;
import java.nio.file.*;
import java.io.*;
public final class SharedCareerStore {
 public static byte[] encode(String json)throws IOException{var out=new ByteArrayOutputStream();try(var gzip=new java.util.zip.GZIPOutputStream(out)){gzip.write(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));}return out.toByteArray();}
 public static String read(Path file)throws IOException{try(var raw=Files.newInputStream(file);var in=new java.util.zip.GZIPInputStream(raw)){return new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}}
 public static void atomic(Path file,byte[] bytes)throws IOException{Files.createDirectories(file.getParent());Path temp=Files.createTempFile(file.getParent(),"career-",".tmp");try(var ch=java.nio.channels.FileChannel.open(temp,StandardOpenOption.WRITE)){var data=java.nio.ByteBuffer.wrap(bytes);while(data.hasRemaining())ch.write(data);ch.force(true);}try{Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}
 public static JsonObject merge(JsonObject baseline,JsonObject local,JsonObject remote){if(local.equals(baseline))return remote.deepCopy();if(remote.equals(baseline))return local.deepCopy();var result=mergeValue(baseline,local,remote,"").getAsJsonObject();int bp=num(baseline,"prestigeLevel"),lp=num(local,"prestigeLevel"),rp=num(remote,"prestigeLevel");if(lp==rp&&lp==bp){long total=Math.max(0,totalXp(remote)+totalXp(local)-totalXp(baseline));int level=1;while(level<50&&total>=1000+level*500){total-=1000+level*500;level++;}result.addProperty("currentLevel",level);result.addProperty("currentXp",level>=50?0:total);}else{var latest=lp>=rp?local:remote;result.addProperty("currentLevel",num(latest,"currentLevel"));result.addProperty("currentXp",num(latest,"currentXp"));result.addProperty("prestigeLevel",Math.max(lp,rp));}return result;}
 private static long totalXp(JsonObject j){long xp=num(j,"currentXp");for(int i=1;i<Math.min(50,num(j,"currentLevel"));i++)xp+=1000+i*500;return xp;}
 private static int num(JsonObject j,String key){return j.has(key)?j.get(key).getAsInt():0;}
 private static JsonElement mergeValue(JsonElement b,JsonElement l,JsonElement r,String key){if(l==null)return r==null?JsonNull.INSTANCE:r.deepCopy();if(r==null||r.isJsonNull())return l.deepCopy();if(java.util.Objects.equals(l,b))return r.deepCopy();if(java.util.Objects.equals(r,b))return l.deepCopy();if(l.isJsonObject()&&r.isJsonObject()){var out=r.getAsJsonObject().deepCopy();for(var e:l.getAsJsonObject().entrySet())out.add(e.getKey(),mergeValue(b!=null&&b.isJsonObject()?b.getAsJsonObject().get(e.getKey()):null,e.getValue(),r.getAsJsonObject().get(e.getKey()),e.getKey()));if(b!=null&&b.isJsonObject())for(var e:b.getAsJsonObject().entrySet())if(!l.getAsJsonObject().has(e.getKey())&&java.util.Objects.equals(r.getAsJsonObject().get(e.getKey()),e.getValue()))out.remove(e.getKey());return out;}if(l.isJsonArray()&&r.isJsonArray()){var out=r.getAsJsonArray().deepCopy();for(var e:l.getAsJsonArray())if(!out.contains(e))out.add(e.deepCopy());return out;}if(l.isJsonPrimitive()&&r.isJsonPrimitive()){var a=l.getAsJsonPrimitive();var c=r.getAsJsonPrimitive();if(a.isNumber()&&c.isNumber()){long value;if(key.startsWith("last")||key.equals("prestigeLevel"))value=Math.max(a.getAsLong(),c.getAsLong());else if(key.equals("dailyDiscounts")||a.getAsString().contains("."))return l.deepCopy();else value=Math.max(0,c.getAsLong()+a.getAsLong()-(b!=null&&b.isJsonPrimitive()?b.getAsLong():0));return new JsonPrimitive(key.startsWith("last")?value:Math.min(Integer.MAX_VALUE,value));}if(a.isBoolean()&&c.isBoolean())return new JsonPrimitive(a.getAsBoolean()||c.getAsBoolean());}return l.deepCopy();}
}
